    let treasure_n = floor( shards_bought / 2 )
    let rest_after_treasure = shards_bought - treasure_n
    let jungle_n = floor( rest_after_treasure / 2 )
    let rest_after_jungle = rest_after_treasure - jungle_n
    let strength_shards = floor( rest_after_jungle / 2 )
    buy( shard_of(family_treasure(), stat_strength()), treasure_n )
    buy( shard_of(family_jungle(), stat_health()), jungle_n )
    buy( shard(stat_strength()), strength_shards )
    buy( shard(stat_health()), rest_after_jungle - strength_shards )
    # heal on spawn before heading back out, unless an enemy is already in reach
    if health() < max_health() and not exists(first(filter(enemies_visible(), in_attack_range()))):
        end_turn()

# fight-back test: we are ahead in the local fight (local_strength > 1) with an enemy champion within 2
let ls = local_strength(4)
let brawl = ls > 1.0 and enemies_within(2) > 0

# retreat toward spawn below 30% health, unless we are winning a local brawl (then fight back)
if not at_spawn and health() < 0.3 * max_health() and not brawl:
    if in_danger():
        let home = closest( spawn_region(ally()) )
        dash_to(0, home)
        dash_to(1, home)
        move_towards(home)
        end_turn()
    recall()
    end_turn()
# bank the bag when hurt and no enemy is close (damage would cancel a recall in danger)
if not at_spawn and gems() > 0 and health() < 0.5 * max_health() and not in_danger():
    recall()
    end_turn()

let ranged = i_am_ranged()
let enemy = weakest( filter( enemies_visible(), in_attack_range() ) )

# focus fire: if the team's chosen target is within our reach, hit it first (2v1 on the same target)
let tt = team_target()
let tt_near = exists(tt) and (distance(position(), unit_position(tt)) <= 1 or (ranged and distance(position(), unit_position(tt)) <= 3))
if tt_near and not contains( spawn_region(enemy()), unit_position(tt) ):
    cast_on(0, tt)
    cast_on(1, tt)
    attack(tt)
    # attack reset: a second basic attack after the first (it does nothing before one)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(tt)
    end_turn()

# an enemy on its own spawn is healed every turn: fighting it there never ends (00reverse-spiral)
if exists(enemy) and not contains( spawn_region(enemy()), unit_position(enemy) ):
    # name the target for the team so allies in reach converge on it
    set_team_target(enemy)
